use vstd::prelude::*;

verus! {
    // Operation selector
    #[verifier(publish)]
    enum OpType { Add, Multiply, LogicalAnd, LogicalOr }

    // Semantic specification of the four operations
    spec fn sem(op: OpType, x: int, y: int) -> int {
        match op {
            OpType::Add => x + y,
            OpType::Multiply => x * y,
            OpType::LogicalAnd => if x != 0 && y != 0 { 1 } else { 0 },
            OpType::LogicalOr  => if x != 0 || y != 0 { 1 } else { 0 },
        }
    }

    // Predicate: id is an identity element for op
    spec fn is_identity(op: OpType, id: int) -> bool {
        forall |x: int| sem(op, x, id) == x && sem(op, id, x) == x
    }

    // Main function: returns Some(id) if an identity exists, None otherwise
    fn ufunc_identity(op: OpType) -> (result: Option<i8>)
        ensures
            match result {
                Some(id) => is_identity(op, id as int),
                None     => forall |id: int| !is_identity(op, id),
            }
    {
        match op {
            // Addition: identity = 0
            OpType::Add => {
                let id0: i8 = 0;
                proof {
                    // Prove 0 is the additive identity
                    assert forall |x: int|
                        sem(OpType::Add, x, id0 as int) == x
                     && sem(OpType::Add, id0 as int, x) == x
                    by {
                        intro x;
                        // sem(Add, x, 0) = x + 0 = x
                        assert sem(OpType::Add, x, id0 as int) == x + (id0 as int);
                        assert x + (id0 as int) == x;
                        // sem(Add, 0, x) = 0 + x = x
                        assert sem(OpType::Add, id0 as int, x) == (id0 as int) + x;
                        assert (id0 as int) + x == x;
                    }
                }
                Some(id0)
            }

            // Multiplication: identity = 1
            OpType::Multiply => {
                let id1: i8 = 1;
                proof {
                    // Prove 1 is the multiplicative identity
                    assert forall |x: int|
                        sem(OpType::Multiply, x, id1 as int) == x
                     && sem(OpType::Multiply, id1 as int, x) == x
                    by {
                        intro x;
                        // sem(Multiply, x, 1) = x * 1 = x
                        assert sem(OpType::Multiply, x, id1 as int) == x * (id1 as int);
                        assert x * (id1 as int) == x;
                        // sem(Multiply, 1, x) = 1 * x = x
                        assert sem(OpType::Multiply, id1 as int, x) == (id1 as int) * x;
                        assert (id1 as int) * x == x;
                    }
                }
                Some(id1)
            }

            // Logical AND: no identity
            OpType::LogicalAnd => {
                proof {
                    // Show that for every candidate id, it fails to be an identity
                    assert forall |id: int| !is_identity(OpType::LogicalAnd, id)
                    by {
                        intro id;
                        // witness x = 2: sem(AND, 2, id) ∈ {0,1} ≠ 2
                        assert sem(OpType::LogicalAnd, 2, id) != 2
                        by {
                            if id == 0 {
                                assert sem(OpType::LogicalAnd, 2, id) == 0;
                                assert 0 != 2;
                            } else {
                                assert sem(OpType::LogicalAnd, 2, id) == 1;
                                assert 1 != 2;
                            }
                        }
                    }
                }
                None
            }

            // Logical OR: no identity
            OpType::LogicalOr => {
                proof {
                    // Show that for every candidate id, it fails to be an identity
                    assert forall |id: int| !is_identity(OpType::LogicalOr, id)
                    by {
                        intro id;
                        // witness x = 2: sem(OR, 2, id) = 1 ≠ 2
                        assert sem(OpType::LogicalOr, 2, id) != 2
                        by {
                            // regardless of id, sem(...) = 1
                            assert sem(OpType::LogicalOr, 2, id) == 1;
                            assert 1 != 2;
                        }
                    }
                }
                None
            }
        }
    }
}

